package com.example.uploads;

import static org.junit.jupiter.api.Assertions.assertTrue;

import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class UploadsControlTest {
    @TempDir
    Path root;

    @Test
    void benignControl() throws Exception {
        Files.write(Paths.get(System.getenv("CORSAIR_MARKER_DIR"), "start"), new byte[0]);
        Path dir = Files.createDirectory(root.resolve("uploads"));
        Uploads.save(dir, "photo.txt", "payload");
        boolean holds = "payload".equals(new String(Files.readAllBytes(dir.resolve("photo.txt")), StandardCharsets.UTF_8));
        Files.write(Paths.get(System.getenv("CORSAIR_MARKER_DIR"), "check"), (holds ? "holds" : "violated").getBytes("UTF-8"));
        assertTrue(holds, System.getenv("CORSAIR_TOKEN"));
        Files.write(Paths.get(System.getenv("CORSAIR_MARKER_DIR"), "end"), new byte[0]);
    }
}

