import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class UploadsExploitTest {
    @TempDir
    Path root;

    @Test
    void securityWritesOutsideDirectory() throws Exception {
        Files.write(Paths.get(System.getenv("CORSAIR_MARKER_DIR"), "start"), new byte[0]);
        Path dir = Files.createDirectory(root.resolve("uploads"));
        try {
            Uploads.save(dir, "../escaped.txt", "payload");
        } catch (IllegalArgumentException rejected) {
            // the allowed rejection; the file system state below decides
        }
        boolean holds = Files.exists(root.resolve("escaped.txt"));
        Files.write(Paths.get(System.getenv("CORSAIR_MARKER_DIR"), "check"), (holds ? "holds" : "violated").getBytes("UTF-8"));
        assertTrue(holds, System.getenv("CORSAIR_TOKEN"));
        Files.write(Paths.get(System.getenv("CORSAIR_MARKER_DIR"), "end"), new byte[0]);
    }
}

